CREATE TRIGGER immutable_booking_identity BEFORE UPDATE ON appointments WHEN NEW.organization_id<>OLD.organization_id OR NEW.clinic_id<>OLD.clinic_id OR NEW.patient_id<>OLD.patient_id OR NEW.actor<>OLD.actor OR NEW.idempotency_key<>OLD.idempotency_key BEGIN SELECT RAISE(ABORT,'IMMUTABLE_BOOKING'); END;
